  from (values
    (442, 'govt_technical', 'bec-gt-concept', 'concept', 1, 'बिजली परिपथ — SSC JE / RRB JE',
     $j${"text":"बिजली का परिपथ (circuit) तभी चलता है जब रास्ता बंद हो। Ohm's law के अनुसार V = IR, यानी वोल्टेज करंट और प्रतिरोध (resistance) से जुड़ा है। Series में प्रतिरोध जुड़ते हैं, parallel में कुल प्रतिरोध कम होता है। Kirchhoff's current law: किसी जंक्शन पर आया करंट = गया करंट।","note":"V = IR · Series: R जोड़ो · Parallel: 1/R = Σ(1/R)"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (442, 'govt_technical', 'bec-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"V = I × R · P = V × I · Series: R = R₁ + R₂ · Parallel: 1/R = 1/R₁ + 1/R₂","explanation":"Resistance का unit ohm (Ω), current का unit ampere (A)"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (442, 'govt_technical', 'bec-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"12 V की supply से 4 Ω का resistor जुड़ा है। Current कितना?","solution":"I = V ÷ R = 12 ÷ 4 = 3","answer":"3 A"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (442, 'govt_technical', 'bec-gt-mcq', 'mcq', 4, 'JE MCQs',
