     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),

    (443, 'govt_technical', 'bel-gt-concept', 'concept', 1, 'बेसिक इलेक्ट्रॉनिक्स — SSC JE / RRB JE',
     $j${"text":"Semiconductor (जैसे silicon और germanium) में conductivity बीच की होती है। Diode एक ही दिशा में करंट बहने देता है, यानी forward bias में चालू और reverse bias में बंद। Silicon diode का forward voltage लगभग 0.7 V होता है। LED जलती है जब उसमें forward bias लगता है। Zener diode उल्टी दिशा में stable voltage देता है।","note":"Diode = एक दिशा में करंट · Silicon ≈ 0.7 V"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (443, 'govt_technical', 'bel-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"Silicon diode V_forward ≈ 0.7 V · Germanium diode V_forward ≈ 0.3 V","explanation":"Forward bias में diode चालू, reverse bias में बंद (leakage को छोड़कर)"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (443, 'govt_technical', 'bel-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"Silicon diode का forward voltage लगभग कितना?","solution":"Silicon diode में forward voltage ≈ 0.7 V होता है","answer":"≈ 0.7 V"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (443, 'govt_technical', 'bel-gt-mcq', 'mcq', 4, 'JE MCQs',
