     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (444, 'govt_technical', 'em-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"50 Hz supply और 4 poles वाली induction motor की synchronous speed?","solution":"Ns = 120 × 50 ÷ 4 = 1500","answer":"1500 rpm"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (444, 'govt_technical', 'em-gt-mcq', 'mcq', 4, 'JE MCQs',
     $j${"questions":[{"q":"Transformer किस सिद्धांत पर काम करता है?","options":["Mutual induction","Self heating","Photoelectric effect","Hall effect"],"answer":0,"explanation":"Mutual induction"},{"q":"50 Hz, 2 poles की synchronous speed?","options":["3000 rpm","1500 rpm","750 rpm","1000 rpm"],"answer":0,"explanation":"Ns = 120 × 50 ÷ 2 = 3000 rpm"}]}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),

    (445, 'govt_technical', 'mi-gt-concept', 'concept', 1, 'विद्युत मापन — SSC JE / RRB JE',
     $j${"text":"Ammeter हमेशा परिपथ में series में जुड़ता है, ताकि पूरा करंट उससे गुज़रे। Voltmeter हमेशा parallel में जुड़ता है। Multimeter से वोल्टेज, करंट और प्रतिरोध नापे जाते हैं। Wheatstone bridge तब संतुलित (balanced) होता है जब आमने-सामने के अनुपात बराबर हों, और तब galvanometer में करंट शून्य होता है।","note":"Ammeter = series · Voltmeter = parallel"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (445, 'govt_technical', 'mi-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"Wheatstone bridge balance: R₁ ÷ R₂ = R₃ ÷ R₄","explanation":"Balanced bridge में galvanometer में करंट = 0"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (445, 'govt_technical', 'mi-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"Wheatstone bridge में R₁ = 10 Ω, R₂ = 20 Ω, R₃ = 15 Ω है। Balance के लिए R₄ कितना?","solution":"R₁÷R₂ = R₃÷R₄ → 10÷20 = 15÷R₄ → R₄ = 30","answer":"30 Ω"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (445, 'govt_technical', 'mi-gt-mcq', 'mcq', 4, 'JE MCQs',
