     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),

    (446, 'govt_technical', 'ps-gt-concept', 'concept', 1, 'विद्युत पावर सिस्टम — SSC JE / RRB JE',
     $j${"text":"Power transmission में वोल्टेज बढ़ाया जाता है, क्योंकि उसी power के लिए करंट कम होने से I²R loss घटता है। Three-phase सिस्टम में power = √3 × V × I × cosφ। Power factor (cosφ) जितना 1 के पास हो, उतना अच्छा। Transmission lines पर corona और sag भी ध्यान में रखे जाते हैं।","note":"Loss ∝ I²R · Power factor = cosφ"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (446, 'govt_technical', 'ps-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"3-phase power P = √3 × V_L × I_L × cosφ · Copper loss = I² × R","explanation":"√3 ≈ 1.732, V_L = line voltage, I_L = line current"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (446, 'govt_technical', 'ps-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"3-phase supply: V_L = 415 V, I_L = 10 A, cosφ = 0.8। Power कितना?","solution":"P = 1.732 × 415 × 10 × 0.8 ≈ 5750 W","answer":"≈ 5.75 kW"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (446, 'govt_technical', 'ps-gt-mcq', 'mcq', 4, 'JE MCQs',
     $j${"questions":[{"q":"Transmission में voltage बढ़ाने से क्या घटता है?","options":["Voltage","Current (line loss के लिए)","Frequency","Power factor"],"answer":1,"explanation":"Same power के लिए current घटता है, इसलिए I²R loss घटता है"},{"q":"Power factor क्या है?","options":["cosφ","sinφ","tanφ","cotφ"],"answer":0,"explanation":"Power factor = cosφ"}]}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),

    (447, 'govt_technical', 'ue-gt-concept', 'concept', 1, 'विद्युत उपयोग और बिल — SSC JE / RRB JE',
     $j${"text":"बिजली का बिल units (kWh) में बनता है। 1 unit = 1 kWh यानी 1 kW बिजली 1 घंटे तक इस्तेमाल। Energy = Power × Time। Illumination (रोशनी) lumen में नापी जाती है और lux = lumen ÷ m²। Efficient उपकरण (जैसे LED) कम बिजली में ज़्यादा रोशनी देते हैं।","note":"1 unit = 1 kWh · Energy = kW × hours"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (447, 'govt_technical', 'ue-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"Energy (kWh) = Power (kW) × Time (h) · Illumination E (lux) = Lumen ÷ Area (m²)","explanation":"1 unit बिजली = 1 kWh"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (447, 'govt_technical', 'ue-gt-example', 'example', 3, 'Numerical (JE style)',
     $j${"question":"1 kW का heater 5 घंटे चलाया। कितने units खर्च हुए?","solution":"Energy = 1 kW × 5 h = 5 kWh","answer":"5 units"}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (447, 'govt_technical', 'ue-gt-mcq', 'mcq', 4, 'JE MCQs',
     $j${"questions":[{"q":"1 unit बिजली बराबर?","options":["1 kW","1 kWh","1 W","1 kVA"],"answer":1,"explanation":"1 unit = 1 kWh"},{"q":"Illumination किस इकाई में?","options":["Lux","Ohm","Joule","Ampere"],"answer":0,"explanation":"Lux (lumen/m²)"}]}$j$,
     'electrical-engineering', array['rrb-je-cbt2','ssc-je-paper1']::text[]),

    (416, 'govt_technical', 'ca-gt-concept', 'concept', 1, 'करंट अफेयर्स — SSC JE / RRB JE',
     $j${"text":"Current affairs में पिछले लगभग 6 से 12 महीने की महत्वपूर्ण घटनाएँ आती हैं: सरकारी योजनाएँ, खेल, पुरस्कार, अंतरराष्ट्रीय सम्मेलन और नियुक्तियाँ। JE और RRB परीक्षा में GA के हिस्से में करंट अफेयर्स के कुछ सीधे प्रश्न आते हैं। रोज़ का न्यूज़ पढ़ने के बजाय मासिक सारांश (monthly digest) से तैयारी करें।","note":"पिछले 6–12 महीने · मासिक सारांश से पढ़ें"}$j$,
     'general-awareness', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (416, 'govt_technical', 'ca-gt-formula', 'formula', 2, 'मुख्य तथ्य',
     $j${"formula":"तैयारी = पिछले 6–12 महीने × मासिक सारांश × बार-बार revision","explanation":"Static GK और current affairs को साथ पढ़ें, ताकि पूरा संदर्भ समझ आए"}$j$,
     'general-awareness', array['rrb-je-cbt2','ssc-je-paper1']::text[]),
    (416, 'govt_technical', 'ca-gt-example', 'example', 3, 'सरल उदाहरण',
